CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, username text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspace_members(workspace_id uuid REFERENCES workspaces(id),user_id uuid REFERENCES users(id),role text NOT NULL CHECK(role IN ('owner','member')),PRIMARY KEY(workspace_id,user_id));
CREATE INDEX IF NOT EXISTS workspace_member_user ON workspace_members(user_id);
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,description text NOT NULL DEFAULT '',engineering_stage text NOT NULL DEFAULT '定义',business_stage text NOT NULL DEFAULT '投标',start_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS project_workspace ON projects(workspace_id);
CREATE TABLE IF NOT EXISTS departments(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,UNIQUE(project_id,name));
CREATE TABLE IF NOT EXISTS memberships(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN ('manager','editor','reviewer','viewer')),department_id uuid REFERENCES departments(id),table_ids jsonb NOT NULL DEFAULT '[]',hidden_columns jsonb NOT NULL DEFAULT '[]',row_scope text NOT NULL DEFAULT 'all' CHECK(row_scope IN ('all','own')),can_export boolean NOT NULL DEFAULT false,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,user_id));
CREATE INDEX IF NOT EXISTS memberships_user ON memberships(user_id);
CREATE TABLE IF NOT EXISTS data_tables(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),department_id uuid NOT NULL REFERENCES departments(id),name text NOT NULL,description text NOT NULL DEFAULT '',columns jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS data_tables_project ON data_tables(project_id);
CREATE INDEX IF NOT EXISTS data_tables_department ON data_tables(department_id);
CREATE TABLE IF NOT EXISTS records(id uuid PRIMARY KEY,table_id uuid NOT NULL REFERENCES data_tables(id),data jsonb NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','rejected','obsolete')),created_by uuid NOT NULL REFERENCES users(id),version integer NOT NULL DEFAULT 1,supersedes uuid REFERENCES records(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS records_table_status ON records(table_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS records_creator ON records(created_by);
CREATE INDEX IF NOT EXISTS records_supersedes ON records(supersedes);
CREATE TABLE IF NOT EXISTS approvals(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),kind text NOT NULL CHECK(kind IN ('record','access','stage','baseline')),title text NOT NULL,record_id uuid REFERENCES records(id),requester_id uuid NOT NULL REFERENCES users(id),approver_id uuid NOT NULL REFERENCES users(id),payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','withdrawn')),opinion text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,CHECK(requester_id<>approver_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_record ON approvals(record_id) WHERE status='pending' AND record_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS approvals_project ON approvals(project_id,created_at DESC);
CREATE INDEX IF NOT EXISTS approvals_requester ON approvals(requester_id);
CREATE INDEX IF NOT EXISTS approvals_approver ON approvals(approver_id,status);
CREATE TABLE IF NOT EXISTS activities(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),code text NOT NULL,name text NOT NULL,duration integer NOT NULL CHECK(duration>=0 AND duration<=3650),progress numeric NOT NULL DEFAULT 0 CHECK(progress>=0 AND progress<=100),department_id uuid REFERENCES departments(id),predecessors jsonb NOT NULL DEFAULT '[]',version integer NOT NULL DEFAULT 1,UNIQUE(project_id,code));
CREATE INDEX IF NOT EXISTS activities_department ON activities(department_id);
CREATE TABLE IF NOT EXISTS baselines(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,snapshot jsonb NOT NULL,approved_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS baselines_project ON baselines(project_id,created_at DESC);
CREATE TABLE IF NOT EXISTS todos(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),title text NOT NULL,due_date date NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),done boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS todos_project ON todos(project_id,due_date);
CREATE INDEX IF NOT EXISTS todos_owner ON todos(owner_id);
CREATE TABLE IF NOT EXISTS saved_views(id uuid PRIMARY KEY,table_id uuid NOT NULL REFERENCES data_tables(id),user_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,config jsonb NOT NULL,UNIQUE(table_id,user_id,name));
CREATE INDEX IF NOT EXISTS views_user ON saved_views(user_id);
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,snapshot jsonb NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reports_project ON reports(project_id,created_at DESC);
CREATE TABLE IF NOT EXISTS connections(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,engine text NOT NULL CHECK(engine IN ('postgres','mysql')),config_cipher text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS connections_workspace ON connections(workspace_id);
CREATE TABLE IF NOT EXISTS audit_log(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),actor_id uuid REFERENCES users(id),action text NOT NULL,resource_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_workspace ON audit_log(workspace_id,created_at DESC);
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),project_id uuid NOT NULL REFERENCES projects(id),kind text NOT NULL CHECK(kind IN ('approval','todo')),resource_id uuid NOT NULL,title text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS notifications_project ON notifications(project_id);
CREATE TABLE IF NOT EXISTS import_batches(request_key uuid NOT NULL,table_id uuid NOT NULL REFERENCES data_tables(id),user_id uuid NOT NULL REFERENCES users(id),content_hash text NOT NULL,row_count integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,request_key));
CREATE INDEX IF NOT EXISTS import_batches_table ON import_batches(table_id);
CREATE TABLE IF NOT EXISTS workflow_definitions(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),kind text NOT NULL CHECK(kind IN ('record','stage','baseline','access')),name text NOT NULL,steps jsonb NOT NULL,version integer NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,kind,name,version));
CREATE INDEX IF NOT EXISTS workflow_definitions_project ON workflow_definitions(project_id,kind,active);
CREATE TABLE IF NOT EXISTS approval_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,approval_id uuid NOT NULL REFERENCES approvals(id),actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL CHECK(action IN ('submit','approve','reject','withdraw')),node_index integer NOT NULL,node_name text NOT NULL,opinion text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS approval_events_approval ON approval_events(approval_id,id);
CREATE INDEX IF NOT EXISTS approval_events_actor ON approval_events(actor_id);
